# tests/test_parse.py: offline, table-driven test of a small parsing function you own.
# Run with: uv run pytest   (or: python -m pytest)
import json
import pytest


def parse_score(raw: str) -> float:
    """Parse a model reply like '{"score": 0.82}' and enforce the 0..1 range."""
    value = float(json.loads(raw)["score"])
    if not 0.0 <= value <= 1.0:
        raise ValueError(f"score out of range: {value}")
    return value


@pytest.mark.parametrize(
    "raw, expected",
    [('{"score": 0}', 0.0), ('{"score": 0.82}', 0.82), ('{"score": 1}', 1.0)],
)
def test_parse_ok(raw: str, expected: float) -> None:
    assert parse_score(raw) == expected


@pytest.mark.parametrize("raw", ['{"score": 1.5}', '{"score": -0.1}', "not json", "{}"])
def test_parse_rejects_bad_input(raw: str) -> None:
    with pytest.raises((ValueError, KeyError)):  # JSONDecodeError is a ValueError
        parse_score(raw)


if __name__ == "__main__":
    print(parse_score('{"score": 0.82}'))

