from pydantic import BaseModel, ConfigDict, Field, ValidationError, field_validator


class Chunk(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)
    id: str
    text: str = Field(min_length=1)
    score: float = Field(ge=0, le=1)
    tags: list[str] = []

    @field_validator("text")
    @classmethod
    def strip(cls, v: str) -> str:
        return v.strip()


good = Chunk.model_validate_json('{"id": "a1", "text": "  hello  ", "score": 0.7}')
print(good.text, good.model_dump())

# What an LLM returning malformed output looks like, and the error you can show it
try:
    Chunk.model_validate({"id": "a2", "text": "x", "score": 1.7, "extra": True})
except ValidationError as e:
    for err in e.errors():
        print(err["loc"], err["type"], "-", err["msg"])

# The JSON Schema you would give a provider for tool calls or structured output
print(list(Chunk.model_json_schema()["properties"]))

