from typing import Annotated, Protocol

from fastapi import Depends, FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field


class AskIn(BaseModel):
    question: str = Field(min_length=1, max_length=2000)
    top_k: int = Field(5, ge=1, le=20)


class AskOut(BaseModel):
    answer: str
    sources: list[str]


class Answerer(Protocol):
    async def answer(self, question: str, top_k: int) -> AskOut: ...


class RealAnswerer:
    async def answer(self, question: str, top_k: int) -> AskOut:
        raise NotImplementedError("call retrieval + the LLM provider here")


def get_answerer() -> Answerer:
    return RealAnswerer()


app = FastAPI()


@app.post("/ask", response_model=AskOut)
async def ask(body: AskIn, svc: Annotated[Answerer, Depends(get_answerer)]) -> AskOut:
    return await svc.answer(body.question, body.top_k)


class FakeAnswerer:
    async def answer(self, question: str, top_k: int) -> AskOut:
        return AskOut(answer=f"echo: {question}", sources=[f"doc-{i}" for i in range(top_k)])


if __name__ == "__main__":
    app.dependency_overrides[get_answerer] = lambda: FakeAnswerer()   # no network, no keys
    client = TestClient(app)
    ok = client.post("/ask", json={"question": "what is RAG?", "top_k": 2})
    print(ok.status_code, ok.json())
    bad = client.post("/ask", json={"question": "", "top_k": 99})
    print(bad.status_code, [e["loc"] for e in bad.json()["detail"]])

