import asyncio
import random

import httpx

RETRY_STATUS = {429, 500, 502, 503, 504}


async def post_with_retry(client: httpx.AsyncClient, url: str, payload: dict, *, attempts: int = 4) -> httpx.Response:
    for attempt in range(1, attempts + 1):
        try:
            resp = await client.post(url, json=payload)
            if resp.status_code not in RETRY_STATUS:
                return resp                                 # success, or a non-retryable client error
            delay = float(resp.headers.get("retry-after", 0)) or min(8.0, 0.5 * 2 ** (attempt - 1))
        except (httpx.TimeoutException, httpx.TransportError):
            delay = min(8.0, 0.5 * 2 ** (attempt - 1))
        if attempt == attempts:
            break
        await asyncio.sleep(delay * random.uniform(0.5, 1.0))   # jitter
    raise RuntimeError("provider unavailable after retries")


# --- offline test using httpx.MockTransport: first 429, then a timeout, then success ---
calls = {"n": 0}


def handler(request: httpx.Request) -> httpx.Response:
    calls["n"] += 1
    if calls["n"] == 1:
        return httpx.Response(429, headers={"retry-after": "0"})
    if calls["n"] == 2:
        raise httpx.ReadTimeout("slow", request=request)
    return httpx.Response(200, json={"ok": True})


async def main() -> None:
    async with httpx.AsyncClient(transport=httpx.MockTransport(handler), timeout=5) as client:
        resp = await post_with_retry(client, "https://provider.test/v1/generate", {"prompt": "hi"})
        print(resp.status_code, resp.json(), "calls:", calls["n"])


asyncio.run(main())
